mapper.update:
UPDATE iam_idempotency_record
SET request_hash = #{requestHash}, status = #{status}, response_status = NULL,
    response_content_type = NULL, response_body = NULL, expires_at = #{expiresAt}
WHERE tenant_id = #{tenantId} AND idempotency_key = #{key}

UPDATE iam_idempotency_record
SET status = #{committedStatus}, response_status = #{responseStatus},
    response_content_type = #{responseContentType}, response_body = #{responseBody}
WHERE tenant_id = #{tenantId} AND idempotency_key = #{key}
  AND status = #{inFlightStatus}

mapper.delete:
DELETE FROM iam_idempotency_record
WHERE tenant_id = #{tenantId} AND idempotency_key = #{key}
  AND status = #{inFlightStatus}
